import React from "react";
import Assistant from "./components/Assistant/Assistant";
import { Boxes } from "./components/ui/background-boxes";

function App() {
  return (
    <div className="relative w-full min-h-screen overflow-hidden bg-slate-900">
      {/* Animated background - covers full screen */}
      <div className="fixed inset-0 w-full h-full bg-slate-900 z-0">
        <Boxes />
        <div 
          className="absolute inset-0 w-full h-full bg-slate-900 z-20 pointer-events-none" 
          style={{
            maskImage: "radial-gradient(circle at center, transparent 0%, white 100%)",
            WebkitMaskImage: "radial-gradient(circle at center, transparent 0%, white 100%)"
          }} 
        />
      </div>

      {/* Foreground content - Assistant with Orb and Cards */}
      <div className="relative z-30 flex flex-col items-center justify-center min-h-screen">
        <Assistant />
      </div>
    </div>
  );
}

export default App;
